document.getElementById('dialog-content').addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close'){dialog.close();return}if(a==='logout-confirm'){save();try{sessionStorage.removeItem('gfair-draft')}catch{}savedAt='';submitted=false;draft={...draft,content:'',amount:'',contract:'',tags:[]};if(image)URL.revokeObjectURL(image.url);image=null;dialog.close();role='admin';nav('COM-01');return}if(a==='add-row'){const title=document.getElementById('new-title').value.trim();if(!title)return toast('이름 또는 제목을 입력해 주세요.');const s=map.get(current),rr=rows(s);rr.push(s.ui.columns.map((_,i)=>i===0?title:i===1?'G-FAIR KOREA '+event:'미등록'));lists[current]=rr;log('예시 등록',title);dialog.close();render();toast('예시 목록에 추가했습니다.');return}if(a==='att-confirm'){const reason=document.getElementById('att-reason').value.trim();if(!reason)return toast('처리 사유를 입력해 주세요.');const s=map.get(current),rr=rows(s),person=document.getElementById('att-person').value,i=rr.findIndex(r=>r[0]===person),j=s.ui.columns.findIndex(c=>/출석상태/.test(c));if(i>=0&&j>=0)rr[i][j]=document.getElementById('att-state').value;lists[current]=rr;log('출석 상태 변경',person);dialog.close();render();toast('예시 출석 상태를 반영했습니다.');return}dialog.close();if(a==='accept-confirm'){log('통역 요청 수락','해외바이어 A');toast('수락 상태를 확인했습니다. 최종 배정은 담당자가 확정합니다.');nav('PRE-07')}else if(a==='demo-send'){log('발송 검토',current);toast('검토를 완료했습니다. 실제 SMS는 발송하지 않았습니다.')}else if(a==='qr-confirm'){log('QR 완료 확인 예시','해외바이어 A');toast('예시 완료 확인 이력을 남겼습니다.')}else{log('작업 확인',current);toast('예시 화면의 작업을 확인했습니다.')}});
