head=function(s,a=''){if(isMobile(s)&&role!=='admin')return oldHead(s,a);const info=menuInfo(s.id),child=info&&info.owner!==s.id;let title=s.title;if(info&&!child)title=info.item[1];if(child&&s.kind==='form'&&/^BAS-|^NTC-04/.test(s.id))title=info.item[1]+' '+({create:'등록',edit:'수정',detail:'상세'}[viewMode]);return `<div class="pagehead"><div><nav class="breadcrumb" aria-label="현재 위치"><a href="#MON-01">홈</a><span>›</span>${info?`<span>${info.g.name}</span><span>›</span><a href="#${info.owner}">${info.item[1]}</a>`:E(s.groupName)}${child?`<span>›</span><span aria-current="page">${E(title)}</span>`:''}</nav><h1>${E(title)}</h1><p class="subtitle">${E(s.summary)}</p></div><div class="head-actions">${child?A(info.owner,'목록으로'):''}${a}</div></div>`};
const oldNav=nav;
function routeContext(id,mode){const previous=menuOwner(current);if(!window.GFAIR_NAV.has(id))workflowParent=previous;else workflowParent='';if(mode)viewMode=mode;else if(id==='NTC-04'||/^BAS-0[2468]$/.test(id))viewMode='detail';}
