const oldForm=form;
form=function(s){if(s.id==='NTC-04'){const owner=menuOwner(s.id);const board=map.get(owner);s={...s,title:board?.title||s.title}}let html=oldForm(s);if(isMobile(s))return html;if(/^BAS-0[2468]$/.test(s.id)||s.id==='BAS-10'||s.id==='NTC-04'){if(viewMode==='detail'){html=html.replace(/<div class="formfooter">[\s\S]*?<\/div><\/section><\/form>/,`<div class="formfooter">${B('workflow-edit','수정','btn primary')}${A(menuOwner(s.id),'목록으로')}</div></section></form>`)}else html=html.replace('<div class="formfooter">',`<div class="formfooter">${A(menuOwner(s.id),'취소')}`)}return html};
const oldList=list;
