map.set('SURVEY-HOME',{...map.get('SET-05'),id:'SURVEY-HOME',title:'만족도설문 관리'});
const folderShell=shell;
const folderOwner=menuOwner;
menuOwner=function(id){if(['buyer','interpreter'].includes(role)&&/^JNL-/.test(id)&&!window.GFAIR_NAV.has(id))return role==='buyer'?'JNL-BUY':'JNL-EXP';if(id==='PRE-07')return 'PRE-01';return folderOwner(id)};
shell=function(s,body){return `<div class="shell ${menu?'menu-open':''}">${sidebar(s)}<div class="workspace">${top()}<main id="content" class="content ${isMobile(s)?'mobile-content':''}">${body}</main>${window.GFAIR_INCLUDE.footer()}</div></div>`};
const folderJournal=journalList;
journalList=function(s){if(s.journalType){filter.type=s.journalType;return folderJournal(s)}return folderJournal(s)};
const folderList=list;
list=function(s){if(s.journalType)return journalList(s);return folderList(s)};
const folderRows=jRows;
jRows=function(s){const rr=folderRows(s);if(role==='buyOperator')return rr.filter(j=>j.type==='구매');if(role==='exportOperator')return rr.filter(j=>j.type==='수출');return rr};
const folderHead=head;
head=function(s,a=''){let html=folderHead(s,a);const info=menuInfo(s.id);if(info?.parent)html=html.replace(`<a href="#${info.owner}">${info.item[1]}</a>`,`<span>${E(info.parent[1])}</span><span>›</span><a href="#${info.owner}">${E(info.item[1])}</a>`);return html};
const folderGeneric=genericAction;
genericAction=function(label){if(label==='저장'&&viewMode!=='detail'&&/^BAS-0[2468]$/.test(current)){const f=document.getElementById('generic-form');if(!f?.reportValidity())return;const owner=menuOwner(current),parent=map.get(owner),rr=rows(parent),data=Object.fromEntries(new FormData(f)),v=i=>data['field'+i]||'미등록',name=i=>v(i).split(' / ')[0],company=i=>v(i).split(' / ')[1]||'미등록';let record;if(current==='BAS-02')record=[event,v(1),(data['field2-start']||'')+' ~ '+(data['field2-end']||''),v(4),v(5)];if(current==='BAS-04')record=[v(0),name(2),v(3),company(2),event,'고유번호 미확정'];if(current==='BAS-06')record=[v(0),name(1),company(1),v(6),'미발급',event];if(current==='BAS-08')record=[v(0),v(1),v(3),v(4),'미발급',v(5)];if(viewMode==='create')rr.unshift(record);else if(rr[selectedRow])rr[selectedRow]=record;lists[owner]=rr;forms[current]=data;log(viewMode==='create'?'등록':'수정',owner);nav(owner);toast('예시 목록에 저장했습니다.');return}folderGeneric(label)};
const folderRender=render;
render=function(){folderRender();const s=map.get(current);if(!s)return;const info=menuInfo(current);if(info&&!window.GFAIR_NAV.allowed(info.item,role)&&!info.item[2].some(c=>window.GFAIR_NAV.allowed(c,role))){root.innerHTML=shell(s,`${head(s)}<section class="panel pad"><h2>이 역할에서 이용할 수 없는 메뉴입니다.</h2><p>메뉴 권한은 사이트맵 기준입니다. 예시 역할을 변경해 주세요.</p>${A(role==='buyOperator'?'EVT-01':role==='exportOperator'?'PRE-01':'MON-01','이용 가능한 메뉴로')}</section>`);return}
 if(['JNL-BUY','JNL-EXP'].includes(current)){const type=s.journalType;root.querySelector('h1').textContent=s.title;const select=root.querySelector('[name=type]');if(select){select.value=type;select.disabled=true}root.querySelector('.head-actions')?.insertAdjacentHTML('beforeend',A(type==='구매'?'JNL-04':'JNL-05','상담일지 등록','btn primary'));}
 const form=document.getElementById('draft-form');if(form&&current==='JNL-06'&&!form.querySelector('[name=mou]'))form.querySelector('.formgrid')?.insertAdjacentHTML('beforeend',F('MOU 추진현황',`<select name="mou">${O(['해당없음','협의중','체결예정','체결완료'],draft.mou||'해당없음')}</select>`)+F('계약 추진현황',`<select name="contractStatus">${O(['미추진','견적검토','계약협의','계약예정','계약완료'],draft.contractStatus||'미추진')}</select>`));
 if(form&&current==='JNL-05')form.insertAdjacentHTML('afterbegin','<p class="sync-info">명함 이미지를 첨부할 수 있습니다. 명함 OCR은 기술협상에 따라 제공하지 않습니다.</p>');
 const generic=root.querySelector('#generic-form');if(generic&&viewMode==='detail'&&/^BAS-0[2468]$/.test(current)){const r=rows(map.get(menuOwner(current)))[selectedRow];if(r){const saved=forms[current]?.field0===r[0]?forms[current]:{};generic.querySelectorAll('input,textarea').forEach(e=>e.value=saved[e.name]||'');const vals=current==='BAS-04'?{0:r[0],2:r[1]+' / '+r[3],3:r[2],5:r[4]}:current==='BAS-06'?{0:r[0],1:r[1]+' / '+r[2],6:r[3]}:current==='BAS-08'?{0:r[0],1:r[1],3:r[2],4:r[3],5:r[5]}:{1:r[0]+' / '+r[1],4:r[3],5:r[4]};Object.entries(vals).forEach(([i,v])=>{if(generic.elements['field'+i])generic.elements['field'+i].value=v});forms[current]={...Object.fromEntries(new FormData(generic)),...Object.fromEntries(Object.entries(vals).map(([i,v])=>['field'+i,v]))}}}
 if(window.lucide)lucide.createIcons({attrs:{width:20,height:20,'stroke-width':1.6}});
};
